merge into RRL_SCHEMA_MIGRATIONS t using(select '2026-10-12-327-ordinary-onward-consolidation' MIGRATION_ID from dual)s on(t.MIGRATION_ID=s.MIGRATION_ID)when not matched then insert(MIGRATION_ID,DESCRIPTION,APPLIED_AT,APPLIED_BY,SCRIPT_NAME,ROLLBACK_SCRIPT,STATUS)values(s.MIGRATION_ID,'One physical upperHU carries multiple exact ordinary onward ST leaves with per-ST immutable dispatch and outgoing identities',sysdate,user,'apply.sql','rollback.sql','APPLIED');
